def verify_isbn(isbn: str) -> str:
    # Check if the ISBN number is in the correct format
    if not isbn.isdigit() or len(isbn) != 10:
        return "Wrong"

    # Calculate the checksum digit
    checksum = 0
    for i, digit in enumerate(isbn):
        if i % 2 == 0:
            checksum += int(digit)
        else:
            checksum += int(digit) * 3

    # Check if the checksum is correct
    if checksum % 11 == 0:
        return "Right"
    else:
        # Calculate the corrected checksum digit
        corrected_checksum = 11 - (checksum % 11)
        # Return the corrected ISBN number
        return isbn[:-1] + str(corrected_checksum)

